log-to-eventhub:
@{
            try {
                var v = context.Variables;
                var model = System.Text.RegularExpressions.Regex.Replace((string)v.GetValueOrDefault("requestModel", (string)v.GetValueOrDefault("deploymentName", "")), "[^A-Za-z0-9._@\\-]", "_");
                var path = context.Request.OriginalUrl.Path;
                var agent = context.Request.Headers.GetValueOrDefault("User-Agent", "");
                var e = new JObject();
                e["time"] = DateTime.UtcNow.ToString("o");
                e["requestId"] = context.RequestId.ToString();
                e["client"] = (string)v.GetValueOrDefault("clientAddress", context.Request.IpAddress);
                e["method"] = context.Request.Method;
                e["path"] = path.Length > 200 ? path.Substring(0, 200) : path;
                e["api"] = context.Api == null ? "" : context.Api.Name;
                e["product"] = context.Product == null ? "" : context.Product.Id;
                e["subscription"] = context.Subscription == null ? "" : context.Subscription.Id;
                e["callerType"] = (string)v.GetValueOrDefault("callerType", "");
                e["callerId"] = (string)v.GetValueOrDefault("usageId", "");
                e["callerName"] = (string)v.GetValueOrDefault("usageName", "");
                e["model"] = model.Length > 64 ? model.Substring(0, 64) : model;
                e["status"] = context.Response == null ? 0 : context.Response.StatusCode;
                e["errorSource"] = context.LastError == null ? "" : context.LastError.Source;
                e["errorReason"] = context.LastError == null ? "" : context.LastError.Reason;
                e["elapsedMs"] = (long)context.Elapsed.TotalMilliseconds;
                e["userAgent"] = agent.Length > 100 ? agent.Substring(0, 100) : agent;
                return e.ToString(Newtonsoft.Json.Formatting.None);
            } catch {
                return "{\"error\":\"security event not built\"}";
            }
        }
